/*
	20231201  修复搜索-提高正确率
	20231013 更新获取逻辑-尐哖
	注：网站质量不好，容易502，刷新即可

	自动获取搜索地址
	需要使用源变量时，执行下面eval
	eval(String(source.bookSourceComment));

*/
	//获取源变量
	_getData = () => {
		try {
			data = JSON.parse(source.getVariable());
			java.log("保存的url:"+data.url)
			java.head(data.url,{})
		} catch (err) {data = {};}
		return data
 	}
 	//保存源变量 _setData(data)
 _setData = (obj) => {
 	if(typeof obj == "object"){
 		source.setVariable(JSON.stringify(obj));
 	}
 }
 java.log("  ！执行中  ！")

 _getData();

 //获取搜索地址
 _getUrl = () => {
 		java.log("获取最新地址")
 		u=source.getKey().match(/([^\#]+)\#/)[1];
 	let url = org.jsoup.Jsoup.parse(java.ajax(u+"/skin/common/SsJlT_tdpk.js")).select("form").attr("action");
 	//js文件获取失败时用webView加载获取所搜地址
 		if(!url||url==''){
 			java.log("js获取失败，webview加载")

 		h=java.webView(null,u,null);
 		ui = org.jsoup.Jsoup.parse(h)
 		.select(":matches([进入点击]+[搜索查找寻]+)")
 		.attr("onclick").match(/'([^']+)'/)[1];

 		j=java.webView(null,u+ui,null);
 		url = org.jsoup.Jsoup.parse(j)
 		.select(":matches([进入点击]+[搜索查找寻]+)")
 		.attr("onclick").match(/'([^']+)'/)[1];
 		}
 		//如果没获取到正常url，说明改方法了，需要更新书源了！！！
 	return url
 }

